CPC_QUESTIONS.push({"id":"fcc-cpc-326488","sourceQuestionId":"326488","t":"cpc-m08","moduleId":"cpc-m08","q":"Em relação à comunicação dos atos processuais, a citação","o":["válida torna prevento o juízo, induz litispendência, faz litigiosa a coisa e, salvo se ordenada por juiz incompetente, constitui em mora o devedor e interrompe a prescrição.","do demente será feita por mandado judicial, certificando o Oficial de Justiça a impossibilidade mental de cumprimento do ato pelo réu, com o que o juiz nomeará de imediato um curador para o ato e para a defesa ulterior do demente.","não será feita, entre outras situações previstas em lei, salvo para evitar o perecimento do direito, ao cônjuge ou a qualquer parente do morto, consanguíneo ou afim, em linha reta, ou na linha colateral em segundo grau, no dia do falecimento e nos sete dias seguintes.","do réu ausente será feita necessariamente por edital, ou, se ausentou-se para furtar-se ao ato, por hora certa, determinada sempre judicialmente.","será feita, em regra, por Oficial de Justiça, frustrado o cumprimento do ato, realizar-se-á por via postal."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2015 • TEC 326488","source":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2015","subject":"Direito Processual Civil - Da Citação (arts. 238 a 259)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/326488","year":2015,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-328506","sourceQuestionId":"328506","t":"cpc-m08","moduleId":"cpc-m08","q":"A ordem escrita expedida por determinação de um juiz para dar ciência à pessoa que vai ser demandada por outra, a fim de que venha a juízo e se defenda da ação contra si proposta, é conhecida como mandado","o":["de injunção.","de citação.","de segurança.","executivo.","possessório."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AgDP (DPE SP)/DPE SP/Arquivista/2015 • TEC 328506","source":"FCC - AgDP (DPE SP)/DPE SP/Arquivista/2015","subject":"Direito Processual Civil - Da Citação (arts. 238 a 259)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/328506","year":2015,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-200968","sourceQuestionId":"200968","t":"cpc-m08","moduleId":"cpc-m08","q":"Petrus é locador de um imóvel e se ausentou do Brasil sem cientificar o locatário de que deixou na localidade onde está situado o imóvel procurador com poderes para receber citação. Nesse caso, tendo o locatário ajuizado ação objetivando a renovação da locação, Petrus será citado","o":["pelo correio, com aviso de recebimento.","por carta precatória.","por edital, com prazo de 20 dias.","na pessoa do administrador do imóvel encarregado o recebimento dos aluguéis.","por edital, com prazo de 60 dias."],"a":3,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT16/TRT 16/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 200968","source":"FCC - AJ TRT16/TRT 16/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Processual Civil - Da Citação (arts. 238 a 259)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/200968","year":2014,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2638066","sourceQuestionId":"2638066","t":"cpc-m08","moduleId":"cpc-m08","q":"Se o Oficial de Justiça procurar o réu para citá-lo pessoalmente e, encontrando-o, este recusar-se a receber a contrafé, deverá","o":["requisitar força policial para cumprir efetivamente o mandado, o que só se dará quando o réu assiná-lo, dando-se por citado.","atestar o fato ao juiz da causa, que determinará a citação do réu por hora certa.","atestar o fato ao juiz da causa, que determinará a citação do réu por edital.","certificar a recusa do réu, dando-o por citado.","portar por fé a recusa, para que o juiz da causa determine a citação do réu pelo correio."],"a":3,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014 • TEC 2638066","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014","subject":"Direito Processual Civil - Da Citação (arts. 238 a 259)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2638066","year":2014,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2021918","sourceQuestionId":"2021918","t":"cpc-m08","moduleId":"cpc-m08","q":"As cartas","o":["têm caráter itinerante.","não precisam ser cumpridas pelo juízo destinatário se este discordar de seu conteúdo.","podem ser expedidas apenas pelos juízos de primeira instância.","deverão ser expedidas preferencialmente em meio físico e encaminhadas pelos Correios.","são chamadas precatórias quando se dirigirem a autoridade judiciária de outro país."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ass Proc (PGE AM)/PGE AM/2022 • TEC 2021918","source":"FCC - Ass Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021918","year":2022,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1818197","sourceQuestionId":"1818197","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, a carta rogatória será expedida para que órgão jurisdicional","o":["estrangeiro pratique ato de cooperação jurídica internacional, relativo a processo em curso perante órgão jurisdicional brasileiro.","brasileiro pratique ou determine o cumprimento, na área de sua competência territorial, de ato relativo a pedido de cooperação judiciária formulado por órgão jurisdicional de competência territorial diversa.","estrangeiro ou brasileiro pratique ou determine o cumprimento, na área de sua competência territorial, de ato objeto de pedido de cooperação judiciária formulado por juízo arbitral, inclusive os que importem efetivação de tutela provisória.","da primeira instância pratique, na área de sua competência territorial, ato objeto de determinação de Tribunal.","integrante de outro ramo da Justiça brasileira pratique ou determine o cumprimento de ato relativo a pedido de cooperação judiciária."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ Aux (TJ SC)/TJ SC/2021 • TEC 1818197","source":"FCC - TJ Aux (TJ SC)/TJ SC/2021","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1818197","year":2021,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1071912","sourceQuestionId":"1071912","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, a carta precatória","o":["deverá ser instruída com as cópias necessárias à realização do ato deprecado, vedada, em qualquer hipótese, a remessa de documento original.","tem caráter itinerante, podendo, mesmo antes de lhe ser ordenado o cumprimento, ser encaminhada a juízo diverso do que dela consta, a fim de se praticar o ato.","será expedida, preferencialmente, por meio físico, salvo quando enviada a órgão jurisdicional integrante do mesmo tribunal, caso em que adotará preferencialmente o meio eletrônico.","não poderá, em nenhuma hipótese, ter seu cumprimento recusado pelo juízo deprecado, sob pena de, assim o fazendo, incorrer em responsabilidade funcional.","deverá ser transmitida por correio, malote, pela internet ou por qualquer outro meio idôneo que garanta a aferição da sua autenticidade, sendo vedada a transmissão por telefone."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019 • TEC 1071912","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1071912","year":2019,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-410419","sourceQuestionId":"410419","t":"cpc-m08","moduleId":"cpc-m08","q":"João, em razão da existência de foro de eleição, ajuizou em Teresina, execução de título extrajudicial em face de José residente em Roma, na Itália, em local conhecido. A citação de José se fará através de","o":["carta de ordem.","carta rogatória.","carta precatória.","carta arbitral.","edital."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TNS (Pref Teresina)/Pref Teresina/Advogado/2016 • TEC 410419","source":"FCC - TNS (Pref Teresina)/Pref Teresina/Advogado/2016","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/410419","year":2016,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-212399","sourceQuestionId":"212399","t":"cpc-m08","moduleId":"cpc-m08","q":"A carta","o":["precatória não poderá ser devolvida sem cumprimento, havendo expressa disposição legal neste sentido.","de ordem não pode ser transmitida por telegrama ou telefone, por envolver relação de subordinação.","precatória poderá ser apresentada a juízo diverso do que dela consta, a fim de ser praticar o ato.","rogatória, na falta de convenção internacional entre o Brasil e o país rogado, será transmitida por via diplomática, dispensando-se a prévia tradução para a língua do país em que o ato será praticado.","rogatória de justiça estrangeira só será cumprida após a concessão de exequibilidade pelo Supremo Tribunal Federal."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2014 • TEC 212399","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2014","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/212399","year":2014,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3883935","sourceQuestionId":"3883935","t":"cpc-m08","moduleId":"cpc-m08","q":"As prerrogativas da Defensoria Pública visam equilibrar a relação processual diante das dificuldades estruturais da assistência jurídica aos necessitados. No que tange à comunicação dos atos processuais no regime do CPC e legislações correlatas,","o":["nos processos que tramitam sob o rito dos Juizados Especiais Cíveis, a legislação específica estabelece a contagem em dias corridos, mas não veda expressamente a prerrogativa do prazo em dobro em relação à Defensoria Pública.","a intimação pessoal do Defensor Público, realizada mediante carga, remessa dos autos ou acesso ao portal eletrônico próprio, é condição de validade do ato, não sendo suprida pela mera publicação em Diário de Justiça Eletrônico, ainda que conste o nome do membro da instituição.","a contagem do prazo em dobro para a Defensoria Pública inicia-se automaticamente no dia útil seguinte à disponibilização da decisão no sistema eletrônico, independentemente de acesso deliberado do defensor ao arquivo ou sistema.","no cumprimento de sentença contra a Fazenda Pública, o prazo para a Defensoria Pública apresentar impugnação é contado de forma simples, por se tratar de incidente de natureza autônoma.","o benefício do prazo em dobro aplica-se apenas às manifestações de mérito, excluindo-se atos puramente ordinatórios ou administrativos praticados no bojo do processo judicial."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883935","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Das Intimações (arts. 269 a 275)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883935","year":2026,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3472569","sourceQuestionId":"3472569","t":"cpc-m08","moduleId":"cpc-m08","q":"Marcelo foi réu em uma ação de indenização que tramitou perante uma das varas cíveis de Manaus. Ele foi pessoalmente citado, mas não constituiu procurador e tampouco apresentou contestação. Houve sentença de procedência do pedido e, um mês apôs o trânsito em julgado, a parte autora iniciou o cumprimento de sentença para o recebimento dos valores. Houve a expedição de carta com aviso de recebimento para a Intimação de Marcelo no mesmo endereço do processo de conhecimento, mas esta retornou negativa com a informação de que ele havia se mudado. Nesse caso. de acordo com o Código de Processo Civil,","o":["a parte autora deverá promover diligências para localizar o paradeiro de Marcelo, pois o cumprimento de sentença só poderá ser realizado após a intimação pessoal frutífera do devedor.","será necessária a intimação pessoal do devedor para o cumprimento do título judicial e, na hipótese de não localização do devedor, a Defensoria Pública deverá atuar nos autos como curador especial de Marcelo.","reputa-se válida a intimação dirigida ao endereço do réu constante do processo de conhecimento, ainda que não assinada por Marcelo, pois a obrigação de comunicar previamente o juízo acerca da mudança de residência é do devedor.","será necessária a intimação de Marcelo por edital, e se ele não se manifestar nos autos no prazo legal, a Defensoria Pública deverá atuar como curador especial do executado.","deverá ser reconhecida a nulidade total da demanda, tendo em vista que, no processo de conhecimento, não houve nomeação de curador especial ao réu revel, nem a apresentação de contestação."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2025 • TEC 3472569","source":"FCC - DP AM/DPE AM/2025","subject":"Direito Processual Civil - Das Intimações (arts. 269 a 275)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3472569","year":2025,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-789037","sourceQuestionId":"789037","t":"cpc-m08","moduleId":"cpc-m08","q":"No que se refere às intimações,","o":["serão elas feitas pelo correio quando frustrada a realização por oficial de justiça.","presumem-se válidas as intimações dirigidas ao endereço constante dos autos, ainda que não recebidas pessoalmente pelo interessado, se a modificação temporária ou definitiva não tiver sido devidamente comunicada ao juízo.","podem ser feitas por edital, caso necessário, mas não por hora certa, pela natureza do ato processual.","o juiz determinará, de ofício, aquelas intimações em processos findos ou pendentes, em qualquer hipótese.","a parte arguirá sua nulidade em capítulo preliminar do próprio ato que lhe caiba praticar, o qual será tido por intempestivo em caso de reconhecimento do vício."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789037","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Processual Civil - Das Intimações (arts. 269 a 275)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789037","year":2019,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-618099","sourceQuestionId":"618099","t":"cpc-m08","moduleId":"cpc-m08","q":"No tocante às intimações,","o":["presumem-se válidas as intimações dirigidas ao endereço constante dos autos, ainda que não recebidas pessoalmente pelo interessado, se a modificação temporária ou definitiva não tiver sido devidamente comunicada ao juízo, fluindo os prazos a partir da juntada aos autos do comprovante de entrega da correspondência no primitivo endereço.","serão feitas preferencialmente por oficial de justiça; frustrado o ato por esse meio, realizar-se-ão por meio eletrônico ou pelo correio.","somente as citações podem ser feitas por hora certa ou edital; já as intimações podem eventualmente realizar-se por edital, defeso porém o ato com hora certa.","é obrigatório aos advogados promover a intimação do advogado da outra parte, por via postal, juntando-se aos autos em seguida cópia do aviso de recebimento.","o juiz determinará, a requerimento das partes, as intimações em processos pendentes, defeso o ato de ofício."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador Federal/2018 • TEC 618099","source":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador Federal/2018","subject":"Direito Processual Civil - Das Intimações (arts. 269 a 275)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/618099","year":2018,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-664657","sourceQuestionId":"664657","t":"cpc-m08","moduleId":"cpc-m08","q":"A respeito das intimações, considere: I. É obrigatório aos advogados promover a intimação da outra parte por meio do correio, juntando aos autos, a seguir, cópia do ofício de intimação e do aviso de recebimento; frustrada a intimação postal, proceder-se-á ao ato por meio do Diário Oficial eletrônico. II. Em qualquer hipótese, o juiz determinará de ofício as intimações em processos pendentes. III. A intimação será feita pessoalmente ou por hora certa, inexistindo porém a intimação por edital, modo que é restrito à citação e aos atos notariais extrajudiciais. IV. A intimação da União, dos Estados, do Distrito Federal, dos Municípios e de suas respectivas autarquias e fundações de direito público será realizada perante o órgão de Advocacia Pública responsável por sua representação judicial. V. A retirada dos autos do cartório ou da secretaria em carga pelo advogado, por pessoa credenciada a pedido do advogado ou da sociedade de advogados, pela Advocacia Pública, pela Defensoria Pública ou pelo Ministério Público implicará intimação de qualquer decisão contida no processo retirado, ainda que pendente de publicação. Está correto o que consta APENAS de","o":["II, IV e V.","IV e V.","I, II e III.","II e V.","I, III e IV."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2018 • TEC 664657","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2018","subject":"Direito Processual Civil - Das Intimações (arts. 269 a 275)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/664657","year":2018,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488270","sourceQuestionId":"2488270","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, quando a lei prescrever determinada forma,","o":["o juiz invalidará o ato sempre que esta não for respeitada, determinando sua repetição apenas se puder decidir o mérito a favor da parte a quem aproveita a decretação da nulidade.","o juiz invalidará o ato sempre que esta não for respeitada, considerando de nenhum efeito todos os subsequentes, sejam ou não dependentes do ato nulo.","o juiz considerará válido o ato se, realizado de outro modo, lhe alcançar a finalidade.","sob pena de nulidade, a decretação desta poderá ser requerida inclusive pela parte a que lhe deu causa.","o juiz invalidará o ato sempre que esta não for respeitada, determinando, necessariamente, sua repetição."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488270","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488270","year":2025,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2032364","sourceQuestionId":"2032364","t":"cpc-m08","moduleId":"cpc-m08","q":"No que se refere às nulidades processuais, o Código de Processo Civil estabelece:","o":["Quando a lei prescrever determinada forma, o juiz considerará válido o ato se, ainda que realizado de outro modo, a sua finalidade for alcançada.","Quando a lei prescrever determinada forma sob pena de nulidade, tanto o Ministério Público, como as partes, ainda que lhe tenham dado causa, poderão requerer a sua decretação, respondendo posteriormente por eventual litigância de má-fé.","Nos feitos em que o Ministério Público deva intervir, caso não haja intimação de seu membro para acompanhar o processo, o juiz invalidará todos os atos desde o início do processo, pois o prejuízo nesse caso é presumido.","Ainda que pudessem ser reconhecidas de ofício pelo juiz, precluem as nulidades quando a parte não as alega na primeira oportunidade em que lhe couber falar nos autos.","Anulado o ato, todos os atos a ele subsequentes, dele dependentes ou não, serão considerados nulos de pleno direito."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (UNICAMP)/UNICAMP/2022 • TEC 2032364","source":"FCC - Proc (UNICAMP)/UNICAMP/2022","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2032364","year":2022,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2239318","sourceQuestionId":"2239318","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com as normas do Código de Processo Civil em matéria de nulidade,","o":["quando a lei prescrever determinada forma sob pena de nulidade, a decretação desta pode ser requerida por qualquer das partes, inclusive por aquela que lhe deu causa, caso em que ficará responsável pelas custas da repetição do ato.","a inobservância da forma prescrita em lei para a prática do ato acarreta a sua nulidade absoluta, não sendo dado ao juiz considerá-lo válido mesmo quando, realizado de outro modo, tenha alcançado sua finalidade.","a nulidade dos atos deve ser alegada na primeira oportunidade em que couber à parte falar nos autos, sob pena de preclusão; entretanto, essa preclusão não se aplica às nulidades que o juiz deva decretar de ofício.","ainda que possa decidir o mérito a favor da parte a quem aproveite a decretação da nulidade, o juiz não poderá deixar de pronunciá-la e de determinar a repetição, o ato ou o suprimento da sua falta.","se um ato for anulado pela mera inobservância da forma prescrita em lei, preservam-se a validade e a eficácia de todos os atos subsequentes, mesmo que dele dependam."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2239318","source":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2239318","year":2022,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1818194","sourceQuestionId":"1818194","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, o erro de forma do processo acarreta a anulação","o":["de todos os atos do processo, desde o ajuizamento da ação.","dos atos do juiz, mas jamais das partes.","dos atos que não possam ser aproveitados, apenas.","dos atos das partes, mas jamais do juiz.","de todos os atos do processo, desde o despacho inicial."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ Aux (TJ SC)/TJ SC/2021 • TEC 1818194","source":"FCC - TJ Aux (TJ SC)/TJ SC/2021","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1818194","year":2021,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1037215","sourceQuestionId":"1037215","t":"cpc-m08","moduleId":"cpc-m08","q":"O erro de forma do processo","o":["acarreta a ineficácia de todos os atos processuais, que deverão ser repetidos de acordo com a forma prescrita ou não defesa em lei.","acarreta unicamente a anulação dos atos que não possam ser aproveitados, devendo ser praticados os que forem necessários a fim de se observarem as prescrições legais.","não acarreta consequência processual alguma, devendo prevalecer os atos praticados em nome do exercício pleno e efetivo da atividade jurisdicional.","acarreta a inexistência dos atos processuais cujo aproveitamento não seja possível, a serem novamente praticados em tempo razoável.","é mera irregularidade, que só necessitará de ratificação ou convalidação se alguma das partes for menor ou incapaz."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJAL/TJ AL/2019 • TEC 1037215","source":"FCC - JE TJAL/TJ AL/2019","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1037215","year":2019,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1071512","sourceQuestionId":"1071512","t":"cpc-m08","moduleId":"cpc-m08","q":"Considere as seguintes proposições acerca das nulidades: I. Se a parte interessada na declaração da nulidade deixar de alegá-la na primeira oportunidade em que lhe couber falar nos autos, ocorrerá a preclusão, ainda que se trate de nulidade que o juiz deva decretar de ofício. II. Se o processo tiver tramitado sem conhecimento do membro do Ministério Público, em feito no qual devesse intervir, o juiz deverá decretar a invalidade dos atos praticados a partir do momento em que ele deveria ter sido intimado; entretanto, a nulidade só pode ser decretada após a intimação do Ministério Público, que se manifestará sobre a existência ou a inexistência de prejuízo. III. A decretação da nulidade por descumprimento da forma prevista em lei poderá ser requerida pela parte que lhe deu causa, mas ela responderá pelas custas do retardamento do processo, além de incorrer nas sanções previstas para a litigância de má-fé. IV. Nos casos em que puder decidir o mérito a favor da parte a quem aproveite a decretação da nulidade, o juiz não deverá pronunciá-la nem mandará repetir o ato ou suprir-lhe a falta. V. Quando a lei prescrever determinada forma, o juiz considerará válido o ato se, realizado de outro modo, lhe alcançar a finalidade, desde que haja a concordância de todas as partes. De acordo com o Código de Processo Civil, está correto o que consta APENAS de","o":["I e II.","I e III.","II e IV.","III e V.","IV e V."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2019 • TEC 1071512","source":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1071512","year":2019,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592909","sourceQuestionId":"592909","t":"cpc-m08","moduleId":"cpc-m08","q":"Concernente às nulidades processuais, considere: I. A nulidade dos atos deve ser alegada na primeira oportunidade em que couber à parte falar nos autos, ainda que essa nulidade tenha sido decretada de ofício pelo juiz. II. Anulado o ato, consideram-se de nenhum efeito todos os subsequentes que dele dependam, todavia, a nulidade de uma parte do ato não prejudicará as outras que dela sejam independentes. III. Quando a lei prescrever determinada forma sob pena de nulidade, a decretação desta pode ser requerida até mesmo pela parte que lhe deu causa, por se tratar de ato que não se convalida ou ratifica. IV. O erro de forma do processo acarreta unicamente a anulação dos atos que não possam ser aproveitados, devendo ser praticados os que forem necessários a fim de se observarem as prescrições legais e aproveitando-se os atos praticados, desde que não resulte prejuízo à defesa de qualquer parte. Está correto o que se afirma APENAS em","o":["I, II e III.","II e IV.","II, III e IV.","I, III e IV.","I e III."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2018 • TEC 592909","source":"FCC - Proc (PGE TO)/PGE TO/2018","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592909","year":2018,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-537020","sourceQuestionId":"537020","t":"cpc-m08","moduleId":"cpc-m08","q":"Sobre os atos processuais, nulidades e valor da causa, o Código de Processo Civil estabelece:","o":["A nulidade por ausência de intimação do Ministério Público para acompanhar o feito em que deveria intervir pode ser decretada independentemente de sua manifestação sobre a inexistência de prejuízo, que sempre se presume.","Ao pronunciar a nulidade, o juiz declarará que atos são atingidos e ordenará as providências necessárias a fim de que sejam repetidos ou retificados, mesmo quando não prejudicar a parte.","O valor da causa será, na ação de cobrança de dívida, a soma monetariamente corrigida do principal, dos juros de mora vencidos e de outras penalidades, se houver, até a data de propositura da ação, e, na ação indenizatória, inclusive a fundada em dano moral, o valor pretendido, cabendo ao juiz, desde que por requerimento da parte contrária, corrigir o valor da causa quando verificar que não corresponde ao conteúdo patrimonial em discussão ou ao proveito econômico perseguido.","O juízo arbitral poderá expedir carta arbitral, para que órgão do Poder Judiciário pratique ou determine o cumprimento, na área de sua competência territorial, de ato objeto de pedido de cooperação judiciária, exceto os que importem efetivação de tutela provisória.","A nulidade dos atos deve ser alegada na primeira oportunidade em que couber à parte falar nos autos, sob pena de preclusão, que não ocorrerá quanto às nulidades que o juiz deva decretar de ofício ou provando a parte legítimo impedimento para alegação oportuna."],"a":4,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT (CSJT)/CSJT/2017 • TEC 537020","source":"FCC - JT (CSJT)/CSJT/2017","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/537020","year":2017,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-396148","sourceQuestionId":"396148","t":"cpc-m08","moduleId":"cpc-m08","q":"Sobre a nulidade dos atos processuais, é correto afirmar que","o":["se verifica independentemente da existência de prejuízo.","o juiz não a pronunciará quando puder decidir o mérito a favor da parte a quem aproveite.","pode ser alegada, em regra, em qualquer momento, não estando sujeita a preclusão.","o erro de forma invalida o ato ainda que possa ser aproveitado sem prejuízo à defesa das partes.","sua decretação pode ser requerida pela parte que lhe der causa, quando a lei prescrever determinada forma para o ato."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2016 • TEC 396148","source":"FCC - DP BA/DPE BA/2016","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/396148","year":2016,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-291966","sourceQuestionId":"291966","t":"cpc-m08","moduleId":"cpc-m08","q":"As nulidades processuais civis,","o":["só podem ser declaradas após provocação das partes, vedado ao juiz reconhecê-las de ofício, pelo caráter privado das normas do processo civil.","devem ser declaradas necessariamente sempre que a matéria disser respeito a questões de ordem pública.","serão decretadas de imediato se a citação do réu for irregular, sem possibilidade de regularização por seu comparecimento espontâneo aos autos.","por falta de intervenção do Ministério Público em processo com interesse de incapazes, são insanáveis, haja ou não prejuízo ao incapaz.","são passíveis de sanação, pela incidência do princípio da instrumentalidade das formas."],"a":4,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJRR/TJ RR/2015 • TEC 291966","source":"FCC - JE TJRR/TJ RR/2015","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/291966","year":2015,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3670623","sourceQuestionId":"3670623","t":"cpc-m08","moduleId":"cpc-m08","q":"NÃO representa motivo justificador da distribuição de causas por dependência a","o":["existência de conexão entre elas.","existência de continência entre elas, nos casos em que a ação continente tiver sido proposta anteriormente.","reiteração de pedido antes formulado em processo extinto sem resolução de mérito, ainda que em lIitisconsórcio com outros autores não participantes do primeiro processo.","possibilidade de prolação de decisões conflitantes acaso decididas separadamente, ainda que não haja conexão entre elas.","apresentação de oposição."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670623","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Distribuição e do Registro (arts. 284 a 290)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670623","year":2025,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3956203","sourceQuestionId":"3956203","t":"cpc-m08","moduleId":"cpc-m08","q":"Para responder as questões de números 50 e 51 considere a existência de ação de reintegração de posse promovida por pessoa física em face de coletividade. A Defensoria Pública, atuando na qualidade de custos vulnerabilis, apresentou contestação e, na ocasião, não tinha informações a respeito do valor do terreno objeto da lide. Após a perícia, houve a comprovação de que o valor do terreno era bastante superior ao indicado pelo autor da ação. Nesse caso,","o":["houve preclusão da impugnação do valor da causa por não ter sido arguida em contestação, não podendo ser modificado o conteúdo econômico ou ao proveito econômico perseguido pelo autor após fase processual.","houve preclusão da impugnação do valor da causa por não ter sido arguida em contestação, podendo ser modificado o conteúdo econômico apenas em sentença, ocasião em que o novo valor atribuído determinará o recolhimento das custas e despesas judiciais futuras.","o juiz corrigirá, de ofício e por arbitramento, o valor da causa quando verificar que não corresponde ao conteúdo patrimonial em discussão, contudo sem a possibilidade de complementação de custas iniciais, valendo-se o novo valor para determinar as custas e despesas judiciais futuras.","o juiz corrigirá, de ofício e por arbitramento, o valor da causa quando verificar que não corresponde ao conteúdo patrimonial em discussão, caso em que se procederá o recolhimento das custas correspondentes.","houve preclusão da impugnação do valor da causa por não ter sido arguida em contestação, podendo ser modificado o conteúdo econômico apenas em sentença, ocasião em que se procederá ao recolhimento das custas iniciais correspondentes e determinará o recolhimento das custas e despesas judiciais futuras."],"a":3,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2026 • TEC 3956203","source":"FCC - DP BA/DPE BA/2026","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3956203","year":2026,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3542710","sourceQuestionId":"3542710","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, a impugnação ao valor da causa atribuido pelo autor deverá ser formulada","o":["em preliminar da contestação, sob pena de preclusão para a parte.","em preliminar da contestação, mas não se sujeita a preclusão, podendo ser suscitada a qualquer tempo, inclusive em apelação ou contrarrazões de apelação, desde que antes do trânsito em julgado.","em preliminar da contestação, mas não se sujeita a preclusão, podendo ser suscitada a qualquer tempo, desde que anteriormente à prolação de sentença ou à decisão saneadora, se não ocorrer o julgamento antecipado.","no prazo de contestação, mas em petição a ela apartada sob pena de preclusão.","até o saneamento do processo, por meio de petição específica, que será processada em autos próprios."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025 • TEC 3542710","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3542710","year":2025,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126466","sourceQuestionId":"3126466","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, o valor da causa será","o":["corrigido de ofício e por arbitramento quando o juiz verificar que não corresponde ao conteúdo patrimonial em discussão ou ao proveito econômico perseguindo pelo autor.","impugnado pelo réu em incidente autônomo, distribuído por dependência ao processos principal.","o valor do pedido principal, na ação em que houver pedidos alternativos.","a quantia correspondente à somatória do pedido principal com o subsídio nas ações em que este foi formulado.","dispensado, se a causa não tiver conteúdo econômico imediatamente aferível."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126466","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126466","year":2024,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3227482","sourceQuestionId":"3227482","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, o valor da causa será, na","o":["ação indenizatória, inclusive a fundada em dano moral, o valor pretendido.","ação em que há cumulação de pedidos o de maior valor.","reconvenção o que constar da petição inicial","ação de alimentos, o valor de uma prestação alimentícia.","ação em que houver pedido subsidiário, a soma deste com o valor do pedido principal."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3227482","source":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3227482","year":2024,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3678191","sourceQuestionId":"3678191","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, a respeito do valor da causa,","o":["nas ações em que houver pedido subsidiário, o valor da causa deve ser a soma dos pedidos principal e subsidiário.","a toda causa será atribuído valor certo, com exceção das ações indenizatórias fundadas em dano moral.","o juiz corrigirá, de ofício e por arbitramento, o valor da causa quando verificar que não corresponde ao conteúdo patrimonial em discussão.","o réu poderá impugnar, a qualquer momento processual, o valor atribuído à causa pelo autor.","à impugnação ao valor da causa deve ser apresentada em incidente apartado, intimando-se o autor, na pessoa de seu advogado, para apresentar resposta no prazo de 15 dias."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT7/TRT 7/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3678191","source":"FCC - AJ TRT7/TRT 7/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3678191","year":2024,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2390170","sourceQuestionId":"2390170","t":"cpc-m08","moduleId":"cpc-m08","q":"Cláudia, mulher negra, sofreu conduta racista durante o atendimento que recebeu no estabelecimento de uma empresa sediada na capital paulista e, por este motivo, procurou a orientação e atuação da Defensoria Pública do Estado de São Paulo. Após esgotadas as tentativas extrajudiciais de solução da questão, a defensora pública decide judicializar a questão, pleiteando a condenação por danos materiais e morais. Diante da natureza dos pedidos, o Código de Processo Civil de 2015","o":["autoriza expressamente a realização de pedido genérico no caso de danos morais, ficando ao prudente arbítrio do juiz a fixação do montante para a indenização, de modo que, de acordo com o entendimento do Superior Tribunal de Justiça, caso seja reconhecido o dano moral, qualquer que seja o valor fixado, não haverá condenação da parte autora às verbas sucumbenciais.","estabelece que o valor da causa deve ser equivalente à soma dos pedidos, incluindo o valor dos danos morais; todavia, o Superior Tribunal de Justiça tem entendido que eventual acolhimento dos pedidos com o arbitramento de danos morais em patamar inferior ao pleiteado não gera sucumbência recíproca para fins de fixação de verbas sucumbenciais.","autoriza expressamente a realização de pedido genérico no caso de danos morais, de modo que o valor da causa deve ser equivalente ao montante dos danos materiais pleiteados; e, de acordo com o entendimento do Superior Tribunal de Justiça, caso seja reconhecido o dano moral, qualquer que seja o valor fixado, não haverá condenação da parte autora às verbas sucumbenciais.","estabelece expressamente que o pedido de danos morais seja certo e determinado, bem como que seja considerado para a indicação do valor da causa, de modo que o Superior Tribunal de Justiça entende que eventual condenação da requerida em valor inferior ao indicado pela parte autora implica em sucumbência recíproca para fins de fixação de verbas sucumbenciais.","estabelece que o valor da causa deve ser equivalente à soma dos pedidos, incluindo o valor dos danos morais; todavia, no caso em tela, eventual parcial procedência do pedido não gera a condenação da parte autora às verbas sucumbenciais no caso de sucumbência recíproca, desde que lhe seja deferida a gratuidade da justiça."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SP/DPE SP/2023 • TEC 2390170","source":"FCC - DP SP/DPE SP/2023","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2390170","year":2023,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592239","sourceQuestionId":"592239","t":"cpc-m08","moduleId":"cpc-m08","q":"A respeito do pedido e do valor da causa no novo Código de Processo Civil,","o":["há previsão expressa da possibilidade de pedido genérico em ação indenizatória por danos morais, razão pela qual o valor da causa poderá se limitar ao valor dos danos materiais.","não mais subsiste o incidente de impugnação ao valor da causa, de modo que a forma e o momento oportuno para impugnação pelo demandado do valor dado à causa na petição inicial é em preliminar de contestação.","no caso de cumulação imprópria de pedidos, o valor da causa deverá ser o equivalente à soma do conteúdo econômico dos pedidos cumulados.","há previsão expressa de que a interpretação do pedido deverá ser feita de maneira restritiva.","ao juiz é vedado de ofício alterar o valor da causa atribuído pelo autor, dependendo de provocação do réu para tanto."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2018 • TEC 592239","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592239","year":2018,"caderno":3,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937727","sourceQuestionId":"3937727","t":"cpc-m09","moduleId":"cpc-m09","q":"Maria, idosa e aposentada, foi diagnóstica com doença grave que necessitava de tratamento específico de saúde. O plano de saúde negou o fornecimento do tratamento indicado pelo médico. Em ação de obrigação de fazer promovida pela Defensoria Pública contra a operadora do plano de saúde, o Juiz condicionou a concessão da tutela de urgência à prestação de caução real. A caução","o":["poderá ser dispensada somente se a demanda não tiver conteúdo econômico em seu objeto.","poderá ser dispensada se a parte economicamente hipossuficiente não puder oferecê-la.","deverá ser exigida independentemente da capacidade econômica da parte em prestá-la.","deverá ser exigida no valor um salário mínimo independentemente da capacidade econômica da parte em prestá-la.","deverá ser exigida no valor um salário mínimo se a parte for economicamente hipossuficiente."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937727","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937727","year":2026,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3986950","sourceQuestionId":"3986950","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela de evidência","o":["depende da demonstração de perigo de dano ou de risco ao resultado útil do processo.","poderá ser concedida liminarmente sempre que o tema for objeto de súmula vinculante, independentemente de prova documental pré constituída.","conserva sua eficácia na pendência do processo e só poderá ser revogada ou modificada com a sentença.","poderá ser concedida se ficar caracterizado o abuso do direito de defesa ou o manifesto propósito protelatório da parte.","poderá ser concedida liminarmente se a petição inicial for instruída com prova documental suficiente dos fatos constitutivos do direito do autor."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026 • TEC 3986950","source":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3986950","year":2026,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3296978","sourceQuestionId":"3296978","t":"cpc-m09","moduleId":"cpc-m09","q":"Lucas ajuizou ação contra empresa para pleitear a restituição de um valor já reconhecido como devido em sede de recurso repetitivo. Considerando que Lucas possui todos os documentos para comprovar as suas alegações, o pedido que deve ser formulado por Lucas na petição inicial é de tutela provisória","o":["de evidência, que poderá ser deferida liminarmente pelo juiz.","de urgência, após o contraditório a que o réu não oponha prova capaz de gerar dúvida razoável.","de evidência, após o contraditório a que o réu não oponha prova capaz de gerar dúvida razoável.","de urgência, que poderá ser deferida liminarmente pelo juiz.","cautelar antecedente, que poderá ser deferida liminarmente pelo juiz."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025 • TEC 3296978","source":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3296978","year":2025,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3355416","sourceQuestionId":"3355416","t":"cpc-m09","moduleId":"cpc-m09","q":"Em ação de divórcio com discussão de guarda, alimentos e partilha de bens, a autora vem enfrentando dificuldades na citação do requerido. Já foram expedidos alguns ofícios de praxe para obtenção de endereços, porém ainda não esgotadas as tentativas de localização pessoal do réu. Diante da demora na localização do requerido, a autora narrou o desejo de conseguir o divórcio independentemente da citação deste. Assim, com o objetivo de dissolver o vínculo matrimonial, no curso da ação de divórcio, a Defensoria Pública poderá requerer","o":["apenas a dispensa da realização da audiência de conciliação obrigatória.","a nomeação antecipada de curador especial ao réu.","a produção antecipada de provas.","a concessão da tutela provisória de evidência.","o julgamento antecipado da lide."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AnaDP (DPE SP)/DPE SP/2025 • TEC 3355416","source":"FCC - AnaDP (DPE SP)/DPE SP/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3355416","year":2025,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3451259","sourceQuestionId":"3451259","t":"cpc-m09","moduleId":"cpc-m09","q":"Considere o Código de Processo Civil brasileiro para responder à questão. A tutela provisória de urgência","o":["só poderá ser modificada ou revogada por sentença, ao final do processo.","deve ser concedida somente após justificação prévia.","não poderá ser requerida incidentalmente no processo.","não será concedida quando houver perigo de irreversibilidade dos efeitos da decisão.","implicará no pagamento de custas, se requerida em caráter incidental."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3451259","source":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3451259","year":2025,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3453281","sourceQuestionId":"3453281","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória de urgência será concedida","o":["quando houver elementos que evidenciem a probabilidade do direito, podendo o Juiz, conforme o caso, exigir caução real ou fidejussória idônea.","independentemente da demonstração de perigo de dano, se ficar demonstrada a violação a enunciado de súmula do Supremo Tribunal Federal.","independentemente da demonstração de perigo de dano, se ficar caracterizado o manifesto propósito protelatório da parte.","quando houver elementos que evidenciem risco ao resultado útil do processo, sendo vedado ao Juiz exigir caução real ou fidejussória idônea.","de forma antecipada mesmo quando houver perigo de irreversibilidade dos efeitos da decisão."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025 • TEC 3453281","source":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3453281","year":2025,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670668","sourceQuestionId":"3670668","t":"cpc-m09","moduleId":"cpc-m09","q":"Considere as assertivas abaixo acerca da tutela provisória de urgência: I. Uma vez concedida e, posteriormente, sendo suspenso o processo, também sua eficácia será suspensa, salvo decisão judicial em sentido contrário. II. Se requerida na forma incidental, independe do pagamento de custas, sendo competente o mesmo juízo que conhecerá do pedido de tutela definitiva. III. O Código de Processo Civil em vigor eliminou a figura das medidas cautelares nominadas, com requisitos próprios, tal como previsto na lei processual anterior. IV. Em sua modalidade antecipada, visa combater o que se denomina “perigo de infrutuosidade” da tutela jurisdicional. Está correto o que se afirma APENAS em","o":["II e III.","III e IV.","I e II.","II e IV.","I e III."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670668","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670668","year":2025,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3679840","sourceQuestionId":"3679840","t":"cpc-m09","moduleId":"cpc-m09","q":"Quanto à tutela de urgência antecipada antecedente:","o":["Não exige a demonstração de risco de dano, mas apenas da aparência do direito almejado.","Uma vez estabilizada, poderá ser invalidada por decisão proferida em ação rescisória, a ser proposta no prazo de até 2 anos.","Exige que, na petição inicial, seja indicado o valor da causa, estabelecido com base no conteúdo econômico da providência pretendida a titulo de antecipação.","Se indeferida pelo juízo, caberá ao autor a emenda da petição Inicial no prazo de 15 dias, sob pena de extinção do processo sem exame de mérito.","Não se estabilizará se o réu interpuser recurso contra a decisão que a concedeu, sendo desinfluente a vontade do autor, expressa na petição inicial, em valer-se de tal sistemática."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2025 • TEC 3679840","source":"FCC - Proc (PGE TO)/PGE TO/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3679840","year":2025,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3021777","sourceQuestionId":"3021777","t":"cpc-m09","moduleId":"cpc-m09","q":"De acordo com o Código de Processo Civil, a tutela de evidência","o":["não pode ser deferida liminarmente.","não pode ter por objeto a obrigação de fazer.","pode ser concedida sem prévia oitiva da parte contra quem ela se dirige.","não pode ser concedida em ação que versar sobre direito indisponível.","só pode ser concedida se houver perigo de dano grave e irreparável."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024 • TEC 3021777","source":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3021777","year":2024,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1981238","sourceQuestionId":"1981238","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela de evidência será concedida quando","o":["houver, independentemente da matéria de fato, houver enunciado de súmula do Supremo Tribunal Federal ou do Superior Tribunal de Justiça.","ficar caracterizado o manifesto propósito protelatório da parte e houver a demonstração de perigo de dano ou de risco ao resultado útil do processo.","a petição inicial for instruída com prova documental suficiente dos fatos constitutivos do direito do autor, independentemente do conteúdo da manifestação do réu.","as alegações de fato puderem ser comprovadas apenas documentalmente e houver tese firmada em julgamento de casos repetitivos.","as alegações de fato puderem ser comprovadas apenas documentalmente e houver a demonstração de perigo de dano ou de risco ao resultado útil do processo."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2022 • TEC 1981238","source":"FCC - DP PB/DPE PB/2022","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1981238","year":2022,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021309","sourceQuestionId":"2021309","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória","o":["pode ser requerida em caráter incidental, e, nesta hipótese, não necessita do pagamento de custas.","será concedida apenas se demonstrado perigo de dano irreversível à parte ou ao processo.","não pode ser modificada pelo juiz que a concedeu.","não está sujeita a recurso.","deve ser pleiteada sempre ao juízo de primeira instância."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Proc (PGE AM)/PGE AM/2022 • TEC 2021309","source":"FCC - Ana Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021309","year":2022,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2073338","sourceQuestionId":"2073338","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela de urgência:","o":["Conserva sua eficácia na pendência do processo, só podendo ser revogada ou modificada por ocasião da prolação da sentença.","Depende da inequivocidade do direito, ou seja, sua certeza, para ser concedida.","Por sua própria natureza, só pode ser concedida liminarmente.","Uma vez concedida, o recurso adequado é a apelação, já que antecipou o provimento jurisdicional final.","Se de natureza cautelar, pode ser efetivada mediante arresto, sequestro, arrolamento de bens, registro de protesto contra alienação de bem e qualquer outra medida idônea para asseguração do direito."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Teresina)/Pref Teresina/2022 • TEC 2073338","source":"FCC - Proc (Teresina)/Pref Teresina/2022","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2073338","year":2022,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1736850","sourceQuestionId":"1736850","t":"cpc-m09","moduleId":"cpc-m09","q":"O valor da causa","o":["constitui matéria dispositiva, não podendo ser alterado, a pedido da parte nem de ofício, se não constar de impugnação, em preliminar de contestação.","corresponde à somatória dos pedidos principal e subsidiário, nas ações que contenham pedidos principal e subsidiário.","deve levar em consideração o pedido de tutela final, no procedimento de tutela antecipada requerida em caráter antecedente.","é utilizado, qualquer que seja, como base de cálculo para fixação dos honorários advocatícios, nas causas em que impossível mensurar o proveito econômico.","pode ser meramente estimado, e não o da condenação pretendida, nas ações nas quais se pede compensação por dano moral."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736850","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736850","year":2021,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1797020","sourceQuestionId":"1797020","t":"cpc-m09","moduleId":"cpc-m09","q":"Uma das inovações trazidas no bojo do Código de Processo Civil de 2015 foi a possibilidade de estabilização das tutelas provisórias. De acordo com as normas estabelecidas pela sistemática processual civil em vigor, a estabilização da tutela","o":["é um fenômeno processual previsto tanto no caso de tutela de urgência, como na tutela da evidência, quando não houver a interposição de recurso oportuno.","uma vez ultrapassado o prazo recursal, a decisão que concedeu a tutela estabiliza-se, tornando seus efeitos imutáveis por força de coisa julgada material.","pode ser somente revista, reformada ou invalidada por meio de ajuizamento de ação rescisória perante o Tribunal competente.","acontece diante da ausência de recurso quanto à concessão de tutela antecipada requerida em caráter antecedente, mas não há previsão quanto às demais espécies de tutela provisória.","se verifica em razão de decisão que concede tutela antecipada, seja em caráter antecedente ou incidental, sem a interposição de recurso oportuno."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SC/DPE SC/2021 • TEC 1797020","source":"FCC - DP SC/DPE SC/2021","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1797020","year":2021,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1147299","sourceQuestionId":"1147299","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória","o":["da evidência será concedida sempre e unicamente quando caracterizado o abuso do direito de defesa ou o manifesto propósito protelatório da parte.","observará o rol taxativo previsto na norma processual.","conserva sua eficácia na pendência do processo, mas pode a qualquer tempo ser modificada, embora não revogada.","de urgência de natureza antecipada só poderá ser concedida após justificação prévia.","de urgência de natureza cautelar pode ser efetivada mediante arresto, sequestro, arrolamento de bens, registro de protesto contra alienação de bem e qualquer outra medida idônea para asseguração do direito."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJMS/TJ MS/2020 • TEC 1147299","source":"FCC - JE TJMS/TJ MS/2020","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1147299","year":2020,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1005258","sourceQuestionId":"1005258","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória","o":["se suspenso o processo, como regra perde ela sua eficácia durante o período respectivo.","de urgência de natureza cautelar pode ser efetivada mediante arresto, sequestro, arrolamento de bens, registro de protesto contra alienação de bem e qualquer outra medida idônea para asseguração do direito.","conserva sua eficácia na pendência do processo, só podendo ser revogada ou modificada por ocasião do saneamento processual ou da sentença.","se requerida em caráter incidental, depende do pagamento de custas processuais.","de urgência só poderá ser concedida em caráter antecedente, pois a urgência precede, quanto aos fatos, o pedido inicial de antecipação tutelar."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Prom Jus (MPE MT)/MPE MT/2019 • TEC 1005258","source":"FCC - Prom Jus (MPE MT)/MPE MT/2019","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1005258","year":2019,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1037216","sourceQuestionId":"1037216","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela da evidência","o":["em nenhuma hipótese admite concessão de liminar judicial.","depende de demonstração de perigo de dano iminente.","depende de demonstração de risco ao resultado útil do processo.","não pode ser concedida se dependente de prova documental dos fatos constitutivos do direito do autor, ainda que o réu não oponha objeção capaz de gerar dúvida razoável.","será concedida, entre outras hipóteses, se se tratar de pedido reipersecutório fundado em prova documental adequada do contrato de depósito, caso em que será decretada a ordem de entrega do objeto custodiado, sob cominação de multa."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJAL/TJ AL/2019 • TEC 1037216","source":"FCC - JE TJAL/TJ AL/2019","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1037216","year":2019,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1072728","sourceQuestionId":"1072728","t":"cpc-m09","moduleId":"cpc-m09","q":"São modalidades de tutela: I. da urgência. II. da evidência. III. antecedente. IV. incidental. De acordo com o atual Código de Processo Civil, a estabilização da tutela provisória se aplica às tutelas previstas nos itens:","o":["I, II e III, apenas.","I, II, III e IV.","II e IV, apenas.","I e III, apenas.","II, III e IV, apenas."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2019 • TEC 1072728","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2019","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1072728","year":2019,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592898","sourceQuestionId":"592898","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória","o":["na decisão em que concedida, modificada ou revogada, o juiz motivará fundamentadamente seu convencimento; quando negar a tutela, porém, não há necessidade de motivação, pois do ato caberá agravo interno ao colegiado.","somente pode fundamentar-se na urgência da situação fática.","de urgência será concedida apenas em caráter antecedente; somente a tutela cautelar pode ser concedida também em caráter incidental.","dependerá do pagamento de custas, quando concedida em caráter incidental.","conserva sua eficácia na pendência do processo, mas pode, a qualquer tempo, ser revogada ou modificada."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2018 • TEC 592898","source":"FCC - Proc (PGE TO)/PGE TO/2018","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592898","year":2018,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-609584","sourceQuestionId":"609584","t":"cpc-m09","moduleId":"cpc-m09","q":"Em relação ao procedimento da tutela cautelar requerida em caráter antecedente,","o":["o indeferimento da tutela cautelar não obsta a que a parte formule o pedido principal, nem influi em seu julgamento, qualquer que seja o motivo do indeferimento.","o réu será citado para, no prazo de quinze dias, contestar o pedido e indicar as provas a serem produzidas; se não contestar, presumir-se-ão os fatos alegados pelo autor como ocorridos.","cessada a eficácia da tutela cautelar, poderá a parte renovar o pedido, mesmo sob igual fundamento, pois na hipótese não haverá a formação de coisa julgada.","efetivada a tutela cautelar, o pedido principal terá de ser formulado pelo autor no prazo de trinta dias, caso em que será apresentado nos mesmos autos em que deduzido o pedido de tutela cautelar, não dependendo do adiantamento de novas custas processuais.","o pedido de tutela cautelar é autônomo, motivo pelo qual o pedido principal deve ser sempre formulado separadamente."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP (DPE AP)/DPE AP/2018 • TEC 609584","source":"FCC - DP (DPE AP)/DPE AP/2018","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/609584","year":2018,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-638411","sourceQuestionId":"638411","t":"cpc-m09","moduleId":"cpc-m09","q":"Quanto às tutelas provisórias, é correto afirmar:","o":["A tutela de urgência de natureza antecipada independe e não se vincula ao perigo de irreversibilidade dos efeitos da decisão.","Não mais existe a tutela de urgência de natureza cautelar no ordenamento processual civil, subsistindo apenas a tutela de urgência antecipatória e a tutela de evidência.","Para conceder a tutela de urgência, o juiz deve exigir caução real ou fidejussória, em nenhuma hipótese podendo dispensá-la se do ato potencialmente ocorrerem danos de difícil reparação à parte adversa.","A concessão de tutela de urgência em caráter liminar não pode ocorrer sem justificação prévia, ainda que sem a citação da parte contrária.","Independentemente da reparação por dano processual, a parte responde pelo prejuízo que a efetivação da tutela de urgência causar à parte adversa se, entre outras hipóteses, o juiz acolher a alegação de decadência ou prescrição da pretensão do autor."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Leg (ALESE)/ALESE/Técnico Jurídica/Apoio Jurídico/2018 • TEC 638411","source":"FCC - Ana Leg (ALESE)/ALESE/Técnico Jurídica/Apoio Jurídico/2018","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/638411","year":2018,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-660221","sourceQuestionId":"660221","t":"cpc-m09","moduleId":"cpc-m09","q":"Acerca da tutela provisória no Código de Processo Civil, é INCORRETO:","o":["A tutela antecipada, concedida nos termos do art. 303 do Código de Processo Civil, torna-se estável se da decisão que a conceder não for interposto o respectivo recurso, mas qualquer das partes poderá demandar a outra com o intuito de rever, reformar ou invalidar a tutela antecipada estabilizada.","A tutela de urgência será concedida quando houver elementos que evidenciem a probabilidade do direito e o perigo de dano ou o risco ao resultado útil do processo.","A tutela de urgência pode ser concedida liminarmente ou após justificação prévia.","A tutela provisória conserva sua eficácia na pendência do processo, mas pode, a qualquer tempo, ser revogada ou modificada.","Durante as férias forenses e nos feriados, não se praticarão atos processuais, excetuando-se, dentre outros, as tutelas provisórias."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2018 • TEC 660221","source":"FCC - DP RS/DPE RS/2018","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/660221","year":2018,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-714245","sourceQuestionId":"714245","t":"cpc-m09","moduleId":"cpc-m09","q":"Considere os seguintes enunciados, que concernem à tutela provisória. I. A tutela provisória conserva sua eficácia na pendência do processo, só podendo ser revogada por ocasião da sentença. II. A tutela provisória de urgência, cautelar ou antecipada, só pode ser concedida em caráter antecedente. III. A tutela de urgência de natureza cautelar pode ser efetivada mediante arresto, sequestro, arrolamento de bens, registro de protesto contra alienação de bem e qualquer outra medida idônea para asseguração do direito. IV. Nos casos em que a urgência for contemporânea à propositura da ação, a petição inicial pode limitar-se ao requerimento da tutela antecipada e à indicação do pedido de tutela final, com a exposição da lide, do direito que se busca realizar e do perigo de dano ou do risco ao resultado útil do processo. Está correto o que se afirma APENAS em","o":["I e III.","I, II e IV.","II, III e IV.","I e II.","III e IV."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Prom Jus (MPE PB)/MPE PB/2018 • TEC 714245","source":"FCC - Prom Jus (MPE PB)/MPE PB/2018","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/714245","year":2018,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-760260","sourceQuestionId":"760260","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória","o":["conserva sua eficácia na pendência do processo, podendo ser revogada ou modificada até o saneador, se novos fatos surgirem a justificar tais alterações.","quando requerida em caráter incidental, depende do pagamento de custas.","quando for de urgência, cautelar ou antecipada, pode ser concedida em caráter antecedente ou incidental.","perderá seus efeitos, como regra, durante o período de suspensão do processo.","será decidida liminarmente, cabendo agravo da decisão que a conceder e apelação da decisão que a denegar, por ser terminativa."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Mun (Caruaru)/Pref Caruaru/2018 • TEC 760260","source":"FCC - Proc Mun (Caruaru)/Pref Caruaru/2018","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/760260","year":2018,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-455534","sourceQuestionId":"455534","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela de urgência, presentes os demais requisitos legais,","o":["só pode ser concedida após justificação prévia e sempre com caução.","pode ser concedida quando houver perigo de dano, ou o risco ao resultado útil do processo.","será concedida quando houver perigo de irreversibilidade dos efeitos da decisão.","não pode ser efetivada através de arrolamento de bens, quando for de natureza cautelar.","só pode ser concedida se o requerente oferecer caução real ou fidejussória idônea."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT11/TRT 11/Judiciária/\"Sem Especialidade\"/2017 • TEC 455534","source":"FCC - AJ TRT11/TRT 11/Judiciária/\"Sem Especialidade\"/2017","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/455534","year":2017,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-460483","sourceQuestionId":"460483","t":"cpc-m09","moduleId":"cpc-m09","q":"Ao disciplinar a tutela provisória, o novo Código de Processo Civil estabelece que","o":["a tutela de urgência não poderá ser concedida sem justificação prévia, salvo se prestada caução idônea, caso em que poderá ser concedida liminarmente.","a tutela antecipada requerida em caráter antecedente torna-se estável se da decisão que a conceder não for interposto o respectivo recurso, caso em que o processo será extinto.","para a concessão da tutela de evidência, exige-se, dentre outros requisitos, a demonstração de perigo de dano ou de risco ao resultado útil do processo.","efetivada a tutela cautelar requerida em caráter antecedente, o pedido principal terá de ser formulado pelo autor no prazo de 15 dias, em ação própria, cujos autos deverão ser apensados aos do pedido cautelar.","é vedada, em qualquer caso, a concessão liminar de tutela de evidência, antes da oitiva da parte contrária."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRE SP/TRE SP/Judiciária/2017 • TEC 460483","source":"FCC - AJ TRE SP/TRE SP/Judiciária/2017","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/460483","year":2017,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-467300","sourceQuestionId":"467300","t":"cpc-m09","moduleId":"cpc-m09","q":"C om base no Código de Processo Civil de 2015, a respeito da tutela provisória, é correto afirmar:","o":["É vedada a exigência de recolhimento de custas para apreciar requerimento de tutela provisória incidental, cuja decisão, se assim subordiná-lo, é recorrível por meio de agravo de instrumento.","A tutela provisória de urgência, assim como a tutela provisória de evidência, pode ser concedida em caráter antecedente ou incidente.","É cabível ação rescisória no prazo decadencial de dois anos da decisão que estabiliza os efeitos da tutela antecipada.","A tutela de evidência prescinde de risco ao resultado útil do processo e do perigo de dano, e poderá ser concedida de maneira liminar quando ficar caracterizado o abuso do direito de defesa.","Na denunciação da lide, fica vedada a concessão de tutela provisória quando o denunciante for o réu."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PR/DPE PR/2017 • TEC 467300","source":"FCC - DP PR/DPE PR/2017","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/467300","year":2017,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-476819","sourceQuestionId":"476819","t":"cpc-m09","moduleId":"cpc-m09","q":"Miguel ajuizou ação de cobrança contra a empresa X, conseguindo demonstrar sua pretensão exclusivamente pela prova documental anexada com a inicial, cuja matéria é objeto de súmula vinculante editada pelo Supremo Tribunal Federal. Neste caso, à luz do Código de Processo Civil, o juiz,","o":["liminarmente, desde que o autor demonstre o perigo de dano ou o risco ao resultado útil do processo, poderá conceder a tutela da evidência.","poderá conceder a tutela de evidência, após ouvir obrigatoriamente a parte contrária, independentemente da demonstração de perigo de dano ou de risco ao resultado útil ao processo.","liminarmente, independentemente da demonstração de perigo de dano ou de risco ao resultado útil ao processo, poderá conceder a tutela da evidência.","poderá conceder a tutela de evidência, após ouvir obrigatoriamente a parte contrária, desde que o autor demonstre o perigo de dano ou o risco ao resultado útil do processo.","poderá conceder a tutela de urgência, após ouvir obrigatoriamente a parte contrária, desde que o autor comprove a probabilidade do direito e o perigo de dano ou o risco ao resultado útil do processo."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT24/TRT 24/Judiciária/Oficial de Justiça Avaliador Federal/2017 • TEC 476819","source":"FCC - AJ TRT24/TRT 24/Judiciária/Oficial de Justiça Avaliador Federal/2017","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/476819","year":2017,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-497865","sourceQuestionId":"497865","t":"cpc-m09","moduleId":"cpc-m09","q":"Em relação às tutelas provisórias, de urgência e da evidência, considere os enunciados seguintes: I. A tutela provisória de urgência, se cautelar, só pode ser concedida em caráter antecedente, podendo a qualquer tempo ser revogada ou modificada. II. A tutela de urgência de natureza cautelar pode ser efetivada mediante arresto, sequestro, arrolamento de bens, registro de protesto contra alienação de bem e qualquer outra medida idônea para asseguração do direito. III. Entre outros motivos, a tutela da evidência será concedida, independentemente da demonstração de perigo de dano ou de risco ao resultado útil do processo, se se tratar de pedido reipersecutório fundado em prova documental adequada do contrato de depósito, caso em que será decretada a ordem de entrega do objeto custodiado, sob cominação de multa. IV. Para a concessão da tutela de urgência, o juiz deve, conforme o caso, exigir caução real ou fidejussória idônea para ressarcir os danos que a outra parte possa vir a sofrer, só podendo a garantia ser dispensada se os requerentes da medida forem menores ou idosos com mais de sessenta anos. Está correto o que se afirma APENAS em","o":["II e III.","I e II.","I, II e IV.","II, III e IV.","I, II e III."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJSC/TJ SC/2017 • TEC 497865","source":"FCC - JE TJSC/TJ SC/2017","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/497865","year":2017,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-362382","sourceQuestionId":"362382","t":"cpc-m09","moduleId":"cpc-m09","q":"Em relação à tutela de urgência, considere: I. Para a concessão da tutela de urgência liminar, o juiz deve exigir de quem a requeira caução real ou fidejussória idônea para ressarcir os danos que a outra parte possa vir a sofrer, o que só poderá ser dispensado se a concessão da medida se der após justificação prévia. II. A tutela de urgência de natureza cautelar pode ser efetivada mediante arresto, sequestro, arrolamento de bens, registro de protesto contra alienação de bem e qualquer outra medida idônea para asseguração do direito. III. A tutela de urgência será concedida quando houver elementos que evidenciem a probabilidade do direito e o perigo de dano ou o risco ao resultado útil do processo. IV. A tutela de urgência de natureza antecipada não será concedida quando houver perigo de irreversibilidade dos efeitos da decisão. Está correto o que se afirma em","o":["I e IV, apenas.","II, III e IV, apenas.","II e III, apenas.","I e III, apenas.","I, II, III e IV."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Pref Campinas)/Pref Campinas/2016 • TEC 362382","source":"FCC - Proc (Pref Campinas)/Pref Campinas/2016","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/362382","year":2016,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-373075","sourceQuestionId":"373075","t":"cpc-m09","moduleId":"cpc-m09","q":"Em processo que tramita na Comarca de Sorriso – MT, o autor ajuizou ação postulando o fornecimento de medicamento de alto custo em face do Estado. Requereu, incidentalmente, a tutela antecipada, alegando que o seu direito era evidente, diante do risco de vida que sofria caso não recebesse o medicamento, comprovado por farta documentação acostada à inicial. O magistrado concedeu a liminar, nos termos em que pleiteada e determinou a intimação do requerido para dar cumprimento à medida. Depois da intimação desta decisão, o requerido cumpriu a liminar nos termos em que determinada e não apresentou qualquer recurso contra a decisão. Diante desta situação, tal decisão","o":["é apta a gerar a estabilização dos seus efeitos, diante da ausência de recurso no prazo oportuno, mas poderá ser revista em ação própria, desde que ajuizada no prazo de dois anos.","não é apta a gerar a estabilização dos seus efeitos, ainda que não tenha sido impugnada mediante recurso, uma vez que este fenômeno processual somente foi previsto para a tutela de urgência antecedente, e não para a tutela incidental.","não é apta a gerar a estabilização dos seus efeitos, uma vez que a lei ressalva a inaplicabilidade deste fenômeno processual para a Fazenda Pública.","é apta a gerar a estabilização dos seus efeitos, por ausência de recurso no prazo oportuno e, assim, fará coisa julgada material, que poderá ser desconstituída por meio de ação rescisória, no prazo de dois anos.","é apta a gerar a estabilização dos seus efeitos, desde que não tenha sido impugnada mediante recurso, uma vez que a lei prevê que somente a tutela da evidência tem a aptidão à estabilização dos seus efeitos."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/2016 • TEC 373075","source":"FCC - Proc (PGE MT)/PGE MT/2016","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373075","year":2016,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-394331","sourceQuestionId":"394331","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória pode fundamentar-se em urgência ou evidência, sendo que","o":["a tutela cautelar de urgência não pode ser efetivada mediante arresto, sequestro ou arrolamento de bens, porque sujeitos a procedimento cautelar específico.","a tutela de evidência será concedida, se demonstrado perigo de dano ou de risco ao resultado útil do processo, quando ficar caracterizado o abuso do direito de defesa ou o manifesto propósito protelatório da parte ou se as alegações de fato puderem ser comprovadas apenas documentalmente e houver tese firmada em julgamento de casos repetitivos ou em súmula vinculante.","a petição inicial da ação que visa à prestação de tutela cautelar em caráter antecedente indicará a lide e seu fundamento, a exposição sumária do direito que se objetiva assegurar e o perigo de dano ou o risco ao resultado útil do processo, mas será a petição inicial indeferida se o pedido tiver natureza antecipatória.","efetivada a tutela cautelar, o pedido principal terá de ser formulado pelo autor no prazo de trinta dias, em autos apensos e mediante o pagamento de novas custas processuais.","requerida a tutela antecipada em caráter antecedente e sendo a urgência contemporânea à propositura da ação, se concedida a tutela antecipada, o autor deverá aditar a petição inicial, com a complementação de sua argumentação, a juntada de novos documentos e a confirmação do pedido de tutela final, em quinze dias ou em outro prazo maior que o juiz fixar."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MA)/PGE MA/2016 • TEC 394331","source":"FCC - Proc (PGE MA)/PGE MA/2016","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/394331","year":2016,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-396152","sourceQuestionId":"396152","t":"cpc-m09","moduleId":"cpc-m09","q":"Sobre a tutela de urgência:","o":["No procedimento da tutela antecipada requerida em caráter antecedente, atendidos os requisitos legais, a parte pode se limitar a requerer tutela antecipada, aditando a inicial depois que concedida a medida, no prazo de 15 dias. Não realizado o aditamento nem interposto o respectivo recurso, o Juiz julgará antecipadamente a lide.","Concedida tutela de urgência, se a sentença for desfavorável, a parte responderá pelo prejuízo decorrente da efetivação da medida, que será apurado, em regra, por meio de ação autônoma.","No procedimento da tutela antecipada requerida em caráter antecedente, a decisão que concede a tutela faz coisa julgada, só podendo ser revista por meio de ação rescisória.","No procedimento da tutela antecipada requerida em caráter antecedente, atendidos os requisitos legais, a parte pode se limitar a requerer tutela antecipada, aditando a inicial depois que concedida a medida, no prazo de 15 dias ou em outro que fixar o juiz. Não realizado o aditamento nem interposto o respectivo recurso, a tutela se tornará estável e o processo será extinto.","A tutela cautelar concedida em caráter antecedente conserva sua eficácia ainda que o juiz extinga o processo sem resolução de mérito em razão de ausência de pressupostos processuais."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2016 • TEC 396152","source":"FCC - DP BA/DPE BA/2016","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/396152","year":2016,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-407115","sourceQuestionId":"407115","t":"cpc-m09","moduleId":"cpc-m09","q":"Considere as seguintes situações abaixo: I. Cumulação de pedidos, um deles restando incontroverso. II. Abuso do direito de defesa. III. Concessão de antecipação de tutela antecedente de urgência. IV. Ação de consignação em pagamento proposta contra dois supostos credores, por não saber a quem se deve pagar. É correto afirmar que","o":["as três primeiras tratam de hipóteses que permitem a tutela provisória da urgência, que não faz coisa julgada, mas pode estabilizar os seus efeitos; a quarta, se trata de litisconsórcio passivo alternativo.","as duas primeiras tratam de hipóteses que permitem a prolação de sentença parcial de mérito, em julgamento que pode produzir coisa julgada; a terceira pode se tornar estável caso a outra parte não apresente recurso; a quarta, se trata de litisconsórcio passivo alternativo.","a primeira trata de hipótese que permite a prolação de sentença parcial de mérito, em julgamento que pode produzir coisa julgada; a segunda, de hipótese que permite a concessão de tutela da evidência, que não faz coisa julgada e nem se estabiliza; a terceira pode se tornar estável caso a outra parte não apresente recurso; a quarta, se trata de litisconsórcio passivo alternativo.","as duas primeiras tratam de hipóteses que permitem a tutela provisória da urgência, que não faz coisa julgada; a terceira pode estabilizar os seus efeitos caso a parte não apresente recurso; a quarta, se trata de litisconsórcio eventual.","a primeira trata de hipótese que permite a prolação de sentença parcial de mérito, em julgamento que pode produzir coisa julgada; a segunda, de tutela da evidência, que não faz coisa julgada; a terceira pode se tornar estável caso a outra parte não apresente recurso; a quarta, se trata de litisconsórcio passivo sucessivo."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP ES/DPE ES/2016 • TEC 407115","source":"FCC - DP ES/DPE ES/2016","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/407115","year":2016,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-435816","sourceQuestionId":"435816","t":"cpc-m09","moduleId":"cpc-m09","q":"Carlos ajuizou ação de obrigação de fazer contra Orlando e teve concedida, em seu favor, tutela de urgência, a qual foi efetivada. No entanto, em sentença, o juiz julgou improcedente o pedido e condenou Carlos a pagar multa por litigância de má-fé. A sentença transitou em julgado. Carlos responde","o":["pelo prejuízo que a efetivação da tutela tiver causado a Orlando, o qual deverá ser abatido do valor da multa por litigância de má-fé. Se possível, a indenização deverá ser liquidada nos mesmos autos.","pela multa por litigância de má-fé, apenas, a qual abrange os prejuízos que a efetivação da tutela tiver causado a Orlando, não cabendo indenização suplementar.","pelo prejuízo que a efetivação da tutela tiver causado a Orlando, o qual deverá ser abatido do valor da multa por litigância de má-fé. A liquidação da indenização deverá ser feita por meio de ação própria, necessariamente.","pelo prejuízo que a efetivação da tutela tiver causado a Orlando, independentemente do pagamento da multa por litigância de má-fé. Se possível, a indenização deverá ser liquidada nos mesmos autos.","pelo prejuízo que a efetivação da tutela tiver causado a Orlando, independentemente do pagamento da multa por litigância de má-fé. A liquidação da indenização deverá ser feita por meio de ação própria, necessariamente."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana (PGE MT)/PGE MT/Bacharel em Direito/2016 • TEC 435816","source":"FCC - Ana (PGE MT)/PGE MT/Bacharel em Direito/2016","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/435816","year":2016,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-271986","sourceQuestionId":"271986","t":"cpc-m09","moduleId":"cpc-m09","q":"Requerida pelo autor antecipação dos efeitos da tutela pretendida, na petição inicial, se a providência pleiteada for de natureza cautelar, o juiz","o":["não conhecerá desse pedido.","suspenderá o processo e determinará que, em dez dias, o autor promova ação cautelar incidente, para que possa conhecer do pedido.","poderá, quando presentes os respectivos pressupostos, deferir a medida cautelar em caráter incidental no processo ajuizado.","indeferirá, de plano, para que não ocorra julgamento extra petita.","deverá marcar prazo de dez dias para o autor emendá- la, sob pena de indeferimento da petição inicial."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT6/TRT 6/2015 • TEC 271986","source":"FCC - JT TRT6/TRT 6/2015","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/271986","year":2015,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-285669","sourceQuestionId":"285669","t":"cpc-m09","moduleId":"cpc-m09","q":"Examine o seguinte artigo de lei: “Cabe à parte propor a ação, no prazo de 30 (trinta) dias, contados da data da efetivação da medida cautelar, quando esta for concedida em procedimento preparatório”. De acordo com entendimento sumulado do STJ, a falta de propositura da ação nesse prazo de trinta dias acarretará:","o":["nenhuma consequência processual, por se tratar de ato discricionário da parte beneficiada pela concessão da medida liminar.","a perda da eficácia da liminar deferida, somente, prosseguindo o processo cautelar em seus ulteriores termos.","a perda da eficácia da liminar deferida e a extinção do processo cautelar.","a impossibilidade jurídica do ajuizamento posterior da ação principal, por perda do objeto e pela ausência de interesse processual de agir.","a manutenção da eficácia da liminar deferida, condicionada porém à prestação de caução real ou fidejussória a ser determinada pelo juiz."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJSC/TJ SC/2015 • TEC 285669","source":"FCC - JE TJSC/TJ SC/2015","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/285669","year":2015,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-300757","sourceQuestionId":"300757","t":"cpc-m09","moduleId":"cpc-m09","q":"Acerca da antecipação dos efeitos da tutela, considere: I. A ação que objetiva abstenção de ato admite cominação de pena pecuniária para o caso de descumprimento de decisão que antecipa os efeitos da tutela. II. É possível a antecipação dos efeitos da tutela em sentença, desde que satisfeitos os requisitos legais. III. Não é possível antecipação dos efeitos da tutela sem comprovação de periculum in mora. IV. O Código de Processo Civil admite expressamente a concessão de tutela antecipada ex officio. Está correto o que consta APENAS em","o":["II e III.","II e IV.","I e III.","I e II.","III e IV."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT15/TRT 15/2015 • TEC 300757","source":"FCC - JT TRT15/TRT 15/2015","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300757","year":2015,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-893768","sourceQuestionId":"893768","t":"cpc-m09","moduleId":"cpc-m09","q":"Em razão de interrupção de serviço de telefonia, Maria ajuizou medida cautelar preparatória no âmbito da qual requereu a concessão de liminar, deferida em 10/06/2015 e efetivada em 20/06/2015. Em 15/07/2015, ajuizou ação principal. Em contestação, a ré pugnou pela extinção do processo cautelar em razão de intempestividade da ação principal. O argumento","o":["deverá ser acolhido, pois a falta de ajuizamento da ação principal, no prazo de 30 dias da concessão da medida liminar, acarreta não somente a perda da eficácia da liminar mas também a extinção do processo cautelar, podendo Maria repetir o pedido mesmo que por igual fundamento.","deverá ser acolhido, pois a falta de ajuizamento da ação principal, no prazo de 30 dias da concessão da medida liminar, acarreta não somente a perda da eficácia da liminar mas também a extinção do processo cautelar, não podendo Maria repetir o pedido, ainda que por novo fundamento.","deverá ser acolhido, pois a falta de ajuizamento da ação principal, no prazo de 30 dias da concessão da medida liminar, acarreta não somente a perda da eficácia da liminar mas também a extinção do processo cautelar, não podendo Maria repetir o pedido, salvo por novo fundamento.","não deverá ser acolhido, pois a ação principal foi ajuizada dentro do prazo de 30 dias, que é contado da efetivação da medida cautelar.","não deverá ser acolhido, pois a falta de ajuizamento da ação principal, no prazo de 30 dias da concessão da liminar, acarreta somente a perda da eficácia da liminar, não a extinção do processo cautelar."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2015 • TEC 893768","source":"FCC - DP MA/DPE MA/2015","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/893768","year":2015,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-216925","sourceQuestionId":"216925","t":"cpc-m09","moduleId":"cpc-m09","q":"Examine os enunciados seguintes, no tocante às medidas cautelares: I. Se por qualquer motivo cessar a eficácia da medida cautelar, poderá a parte repetir o pedido, pelo mesmo ou por novo fundamento. II. As medidas cautelares conservam a sua eficácia no prazo de trinta dias, contados da data da efetivação da medida cautelar, quando esta for concedida em procedimento preparatório, e na pendência ao processo principal; mas podem, a qualquer tempo, ser revogadas ou modificadas. III. A medida cautelar poderá ser substituída, de ofício ou a requerimento de qualquer das partes, pela prestação de caução ou outra garantia menos gravosa para o requerido, sempre que adequada e suficiente para evitar a lesão ou repará-la integralmente. IV. As medidas cautelares serão requeridas ao juiz da causa e, quando preparatórias, ao juiz competente para conhecer da ação principal. Se interposto recurso, a medida cautelar continuará sendo requerida ao juiz competente para o conhecimento da ação principal. Está correto o que se afirma em","o":["III e IV, apenas.","II e III, apenas.","I, II e III, apenas.","II e IV, apenas.","I, II, III e IV."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2014 • TEC 216925","source":"FCC - DP PB/DPE PB/2014","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/216925","year":2014,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-282894","sourceQuestionId":"282894","t":"cpc-m09","moduleId":"cpc-m09","q":"Pedro ajuizou ação cautelar preparatória no âmbito da qual requereu, liminarmente, a suspensão de crédito tributário, o que foi deferido. De acordo com o Código de Processo Civil e com Súmula do Superior Tribunal de Justiça, Pedro deverá propor ação principal no prazo de 30 dias, contados da data da","o":["efetivação da medida, sob pena de extinção do processo principal sem resolução de mérito.","efetivação da medida, sob pena de perda da eficácia da liminar e de extinção do processo cautelar.","propositura da ação cautelar, sob pena de perda da eficácia da liminar e de extinção do processo cautelar.","concessão da liminar, sob pena de perda de sua eficácia e de extinção do processo cautelar.","concessão da liminar, sob pena de extinção do processo principal sem resolução de mérito."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE RN)/PGE RN/2014 • TEC 282894","source":"FCC - Proc (PGE RN)/PGE RN/2014","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/282894","year":2014,"caderno":3,"classificationReason":"Tutela provisória expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2488266","sourceQuestionId":"2488266","t":"cpc-m10","moduleId":"cpc-m10","q":"Acerca da formação, suspensão e extinção do processo, considere: I. Considera-se proposta a ação com a citação. II. Antes de extinguir o processo sem resolução de mérito, o juiz deve conceder à parte oportunidade para, se possível, corrigir o vício. III. Durante a suspensão é vedado praticar qualquer ato processual, podendo o juiz, todavia, determinar a realização de atos urgentes a fim de evitar dano irreparável, salvo no caso de arguição de impedimento e de suspeição. IV. Suspende-se o processo sempre que o requerer o credor. De acordo com o Código de Processo Civil, está correto o que se afirma APENAS em","o":["I e II.","III e IV.","I e IV.","II e III.","I e III."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488266","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488266","year":2025,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3380063","sourceQuestionId":"3380063","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, o seguinte evento não enseja a suspensão do processo:","o":["admissão de incidente de resolução de demandas repetitivas.","convenção das partes.","arguição de suspeição do juiz.","morte de um dos autores, no caso de haver litisconsórcio ativo facultativo.","pedido de gratuidade da justiça formulado após a primeira manifestação da parte na instância."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025 • TEC 3380063","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3380063","year":2025,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2155375","sourceQuestionId":"2155375","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, se o conhecimento do mérito depender de verificação da existência de fato delituoso objeto de ação penal em curso perante a justiça criminal, o juiz","o":["deve extinguir o processo, sem resolução do mérito, por falta de interesse de agir, resguardada a eficácia de medidas de caráter urgente ou satisfativas.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar por prazo indeterminado.","pode determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar pelo prazo máximo de um ano, ao final do qual incumbirá ao juiz cível examinar incidentalmente a questão prévia.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar pelo prazo máximo de três meses, ao final do qual incumbirá ao juiz cível solicitar ao juiz criminal urgência no exame da questão prévia.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar pelo prazo máximo de um ano, podendo ser prorrogado, uma única vez, por igual período."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2022 • TEC 2155375","source":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2155375","year":2022,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2272129","sourceQuestionId":"2272129","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, o processo não será suspenso em razão de","o":["convenção das partes.","concessão de adoção a qualquer das partes, salvo se a parte que tiver adotado for advogada atuante em causa própria e constituir a única patrona da causa.","o advogado responsável pelo processo constituir o único patrono da causa e tornar-se pai.","arguição de impedimento ou de suspeição do juiz, mas, caso venha a ser acolhida, implicará a nulidade dos atos por ele praticados.","admissão de incidente de resolução de demandas repetitivas."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2272129","source":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2272129","year":2022,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-943340","sourceQuestionId":"943340","t":"cpc-m10","moduleId":"cpc-m10","q":"Na fase de saneamento do processo, o juiz verificou que o conhecimento do mérito da demanda dependia da verificação de fato delituoso objeto de inquérito policial, não tendo ainda o Ministério Público ajuizado a correspondente ação penal. Nesse caso, o juiz","o":["pode determinar a suspensão do processo até que se pronuncie a justiça criminal; porém, se a ação penal não for proposta no prazo de 3 (três) meses, contado da intimação do ato de suspensão, deverá dar andamento ao feito e examinar incidentemente a questão prévia.","não pode determinar a suspensão do processo, cabendo-lhe examinar incidentemente a questão prévia, haja vista que as instâncias cível e criminal não se confundem.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo manter o processo suspenso por prazo indeterminado, desde que a ação penal seja proposta no prazo de 3 (três) meses, contado da intimação do ato de suspensão.","somente pode ordenar a suspensão do processo, pelo prazo máximo de 1 (um) ano, a partir de quando venha a ser proposta a ação penal.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, pelo prazo mínimo de 1 (um) ano e máximo de 2 (dois), salvo se o procedimento de investigação criminal vier a ser arquivado, sem o oferecimento de denúncia"],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019 • TEC 943340","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943340","year":2019,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-653959","sourceQuestionId":"653959","t":"cpc-m10","moduleId":"cpc-m10","q":"Tulio ajuizou ação monitória contra Edilson, que tramita regularmente em uma das varas cíveis do Foro Central da Comarca de São Paulo, Capital. Tulio e Edilson são representados em juízo, respectivamente e exclusivamente, pelos advogados Rodolfo e Julia. No curso do processo, durante o mês de Fevereiro deste ano de 2018, Rodolfo, advogado de Tulio, tornou-se pai após o parto de sua esposa. E no mês de abril deste mesmo ano Julia tornou-se mãe. Rodolfo e Julia comunicaram os seus clientes e apresentaram em juízo as respectivas certidões de nascimento. No caso hipotético apresentado, de acordo com o que estabelece o Código de Processo Civil, agiu corretamente o Magistrado que","o":["suspendeu o processo pelo prazo de 8 dias a partir da data do parto da esposa do advogado Rodolfo, e suspendeu o processo pelo prazo de 30 dias a partir da data do parto da advogada Julia.","não suspendeu o processo após o parto da esposa de Rodolfo, e suspendeu o processo pelo prazo de 60 dias a partir da data do parto da advogada Julia.","suspendeu o processo pelo prazo de 5 dias a partir da data do parto da esposa do advogado Rodolfo, e suspendeu o processo pelo prazo de 30 dias a partir da data do parto de Julia.","suspendeu o processo pelo prazo de 5 dias a partir da data do parto da esposa de Rodolfo, e suspendeu o processo pelo prazo de 60 dias a partir da data do parto de Julia.","suspendeu o processo pelo prazo de 20 dias a partir da data do parto da esposa de Rodolfo, e suspendeu o processo pelo prazo de 30 dias a partir da data do parto de Julia."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2018 • TEC 653959","source":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2018","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/653959","year":2018,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-664655","sourceQuestionId":"664655","t":"cpc-m10","moduleId":"cpc-m10","q":"Em relação à formação, suspensão e extinção do processo,","o":["durante a suspensão do processo é defesa a realização de qualquer ato processual, sem exceção, para proteção do princípio da isonomia.","considera-se proposta a ação quando a petição inicial for despachada pelo juiz, mas seus efeitos dependem quanto ao réu de sua citação válida.","se o conhecimento do mérito depender de verificação da existência de fato delituoso, o juiz deve determinar a suspensão do processo até que a justiça criminal se pronuncie; nesse caso, a ação penal deve ser proposta em até seis meses, sob pena de cessação dos efeitos da suspensão.","a extinção do processo sem resolução do mérito, por vício processual, dar-se-á de imediato; já a extinção com resolução de mérito dar se-á somente por sentença, observados o contraditório e a ampla defesa.","suspende-se o processo pela admissão de incidente de resolução de demandas repetitivas."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2018 • TEC 664655","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2018","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/664655","year":2018,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-733920","sourceQuestionId":"733920","t":"cpc-m10","moduleId":"cpc-m10","q":"Diogo ajuizou contra Paulo ação de cobrança de alugueres, vindo a falecer no curso do processo, logo depois e oferecida a contestação e antes de proferida a sentença. Nos termos do Processo Civil, não ajuizada ação de habilitação, ao tomar conhecimento da morte do autor, o juiz deverá","o":["extinguir desde logo o processo sem resolução do mérito, o que não impede o espólio ou os sucessores de renovar a propositura da ação.","extinguir desde logo o processo com resolução do mérito, o que impede o espólio ou os sucessores de renovar a propositura da ação.","suspender o processo e, sem ordenar qualquer intimação, marcar prazo para que seu espólio, quem for o sucessor ou, se for o caso, seus herdeiros manifestem interesse na sucessão processual e promovam a respectiva habilitação, sob pena de extinção do processo sem resolução de mérito.","suspender o processo e determinar a intimação de seu espólio, de quem for o sucessor ou, se for o caso, dos herdeiros, pelos meios de divulgação que reputar mais adequados, para que manifestem interesse na sucessão processual e promovam a respectiva habilitação no prazo designado, sob pena de extinção do processo com resolução de mérito, pela preclusão.","suspender o processo e determinar a intimação de seu espólio, de quem for o sucessor ou, se for o caso, dos herdeiros, pelos meios de divulgação que reputar mais adequados, para que manifestem interesse na sucessão processual e promovam a respectiva habilitação no prazo designado, sob pena de extinção do processo sem resolução de mérito."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE PE)/MPE PE/Administrativa/2018 • TEC 733920","source":"FCC - Tec Min (MPE PE)/MPE PE/Administrativa/2018","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/733920","year":2018,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-456546","sourceQuestionId":"456546","t":"cpc-m10","moduleId":"cpc-m10","q":"Se ocorrer o falecimento do único advogado do réu, o juiz determinará que este constitua novo mandatário no prazo de 15 dias. Decorrido esse prazo sem a constituição de novo mandatário, o juiz","o":["suspenderá o processo pelo prazo de 1 ano.","extinguirá o processo sem resolução de mérito.","suspenderá o processo pelo prazo de 3 meses.","ordenará o prosseguimento do processo à revelia do réu.","nomeará outro advogado para o réu, apesar de não ser beneficiário da Justiça Gratuita."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT11/TRT 11/Administrativa/\"Sem Especialidade\"/2017 • TEC 456546","source":"FCC - TJ TRT11/TRT 11/Administrativa/\"Sem Especialidade\"/2017","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/456546","year":2017,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-537022","sourceQuestionId":"537022","t":"cpc-m10","moduleId":"cpc-m10","q":"Sobre formação, suspensão e extinção do processo, a legislação processual civil estabelece:","o":["Havendo morte do autor, sendo transmissível o direito em litígio e não tendo sido ajuizada a ação de habilitação, o juiz determinará a suspensão do processo e a intimação de seu espólio, de quem for o sucessor ou, se for o caso, dos herdeiros, pelos meios de divulgação que reputar mais adequados, para que manifestem interesse na sucessão processual e promovam a respectiva habilitação no prazo designado, sob pena de extinção do processo sem resolução de mérito.","Durante a suspensão do processo é vedado praticar qualquer ato processual, podendo o juiz, mesmo no caso de arguição de impedimento e de suspeição, determinar a realização de atos urgentes a fim de evitar dano irreparável.","Se o conhecimento do mérito depender de verificação da existência de fato delituoso, o juiz deverá determinar a suspensão do processo até que se pronuncie a justiça criminal, pelo prazo máximo de um ano, ao final do qual incumbirá ao juiz cível examinar incidentemente a questão prévia.","Havendo falecimento de qualquer das partes, proceder-se-á à habilitação, na instância em que estiver, suspendendo-se, a partir de então, o processo para processamento da habilitação, com citação dos requeridos e, se necessário, dilação probatória, que, independentemente da espécie, será feita nos autos do processo principal.","A ação é considerada proposta quando do protocolo da petição inicial, mas somente a citação válida induz litispendência, torna litigiosa a coisa e constitui o devedor em mora, inclusive no caso de inadimplemento de obrigações decorrentes de ato ilícito."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT (CSJT)/CSJT/2017 • TEC 537022","source":"FCC - JT (CSJT)/CSJT/2017","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/537022","year":2017,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-576006","sourceQuestionId":"576006","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o novo Código de Processo Civil, o processo será suspenso pela convenção das partes por prazo máximo","o":["de 30 dias.","de 06 meses.","de 1 ano.","de 05 anos.","igual ao de prescrição ou decadência da pretensão ou direito em causa."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2017 • TEC 576006","source":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2017","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/576006","year":2017,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"});
